def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = bins * 0.25
    score = -np.maximum(0.0, remaining - target) / (bins + 1e-5)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    optimal_residual = bins * 0.1
    score = -np.abs(remaining - optimal_residual)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / (bins + 1e-8)
    score = -1.0 / (np.abs(fill_ratio - 0.5) + 1e-4)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = np.divide(remaining, bins, out=np.zeros_like(bins, dtype=float), where=bins>0)
    score = -np.exp(-4.0 * (ratio - 0.5) ** 2)
    return np.where(remaining < 0, -np.inf, score)

